class Solution:
    def nextGate(self, gates: str, current: str) -> str:
        lo, hi = 0, len(gates)
        while lo < hi:
            mid = (lo + hi) // 2
            if gates[mid] <= current:
                lo = mid + 1
            else:
                hi = mid
        return gates[lo % len(gates)]

code.java:
class Solution {
    public String nextGate(String gates, String current) {
        char c = current.charAt(0);
        int lo = 0, hi = gates.length();
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (gates.charAt(mid) <= c) lo = mid + 1;
            else hi = mid;
        }
        return String.valueOf(gates.charAt(lo % gates.length()));
    }
}

