char* nextGate(char* gates, char* current) {
    int n = strlen(gates);
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (gates[mid] <= current[0]) lo = mid + 1;
        else hi = mid;
    }
    char* out = calloc(2, 1);
    out[0] = gates[lo % n];
    return out;
}
